"""Intent tests for mdata.align_calendar: one calendar, forward fill, and a gap limit (DATA-03, DATA-04)."""

from __future__ import annotations

import pytest

from mdata import GapError, Prices, RawRow
from mdata.calendar import align_calendar


def build_rows(payload: dict) -> list[RawRow]:
    return [RawRow(date=date, ticker=ticker, close=close) for date, ticker, close in payload["rows"]]


def build_prices(payload: dict) -> Prices:
    closes = {ticker: tuple(series) for ticker, series in payload["closes"].items()}
    return Prices(dates=tuple(payload["dates"]), tickers=tuple(payload["tickers"]), closes=closes)


@pytest.mark.intent
def test_tc02_one_calendar_with_filled_gaps(golden):
    source, expected = golden("mdata", "TC-02")
    prices = align_calendar(build_rows(source), max_gap=source["max_gap"])
    assert prices == build_prices(expected)


@pytest.mark.intent
def test_tc02_calendar_starts_on_first_date_every_ticker_has(golden):
    source, expected = golden("mdata", "TC-02")
    prices = align_calendar(build_rows(source), max_gap=source["max_gap"])
    assert prices.dates == tuple(expected["dates"])
    assert prices.tickers == tuple(expected["tickers"])


@pytest.mark.intent
def test_tc02_missing_dates_take_previous_close(golden):
    source, expected = golden("mdata", "TC-02")
    prices = align_calendar(build_rows(source), max_gap=source["max_gap"])
    for ticker in expected["tickers"]:
        assert prices.closes[ticker] == tuple(expected["closes"][ticker])


@pytest.mark.intent
def test_tc02_default_max_gap_gives_same_answer(golden):
    source, expected = golden("mdata", "TC-02")
    assert align_calendar(build_rows(source)) == build_prices(expected)


@pytest.mark.intent
def test_tc03_six_date_gap_raises_gap_error_naming_ticker(golden):
    source, expected = golden("mdata", "TC-03")
    assert expected["raises"] == GapError.__name__
    with pytest.raises(GapError, match=expected["match"]):
        align_calendar(build_rows(source), max_gap=source["max_gap"])


@pytest.mark.intent
def test_tc03_default_max_gap_raises_gap_error(golden):
    source, expected = golden("mdata", "TC-03")
    with pytest.raises(GapError, match=expected["match"]):
        align_calendar(build_rows(source))


@pytest.mark.intent
def test_tc03_gap_within_a_larger_max_gap_is_filled(golden):
    source, expected = golden("mdata", "TC-03")
    rows = build_rows(source)
    gap_ticker = expected["match"]
    prices = align_calendar(rows, max_gap=source["max_gap"] + 1)
    all_dates = sorted({row.date for row in rows})
    assert prices.dates == tuple(all_dates)
    own = {row.date: row.close for row in rows if row.ticker == gap_ticker}
    last = None
    for date, close in zip(prices.dates, prices.closes[gap_ticker], strict=True):
        last = own.get(date, last)
        assert close == last

